import { NextRequest, NextResponse } from "next/server";
import { eq } from "drizzle-orm";
import { z } from "zod";
import { Permission, RequestStatus } from "@accessbuddy/shared";
import { fobRequests } from "@accessbuddy/db";
import { getAuthUser } from "@/lib/auth";
import { resolveTenant } from "@/lib/tenant";
import { checkPermission } from "@/lib/permissions";
import { withTenant } from "@/lib/with-tenant";
import { transitionRequest } from "@/lib/services/requests";

const bodySchema = z.object({
  reason: z.string().min(1, "Reason is required").max(500),
});

const REQUIRABLE_STATUSES: string[] = [RequestStatus.SUBMITTED, RequestStatus.AWAITING_APPROVAL];

/**
 * Admin "require payment". Moves an unpaid request to awaiting_payment,
 * creates the Stripe payment intent if the request never got one, and emails
 * the member a payment link plus a signed cancel link. Valid from SUBMITTED
 * (member abandoned the payment step) and AWAITING_APPROVAL (exemption
 * granted in error, or a free request that should have been charged).
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string; id: string }> }
) {
  try {
    const auth = await getAuthUser();
    if (!auth) {
      return NextResponse.json({ error: "Authentication required" }, { status: 401 });
    }

    const { slug, id: requestId } = await params;
    const tenant = await resolveTenant(slug);
    if (!tenant) {
      return NextResponse.json({ error: "Organisation not found" }, { status: 404 });
    }

    // Requiring payment is the mirror of granting an exemption, so it sits
    // behind the same approver-level permission.
    const permResult = checkPermission(auth, tenant.id, Permission.APPROVE_EXEMPTION);
    if (!permResult.granted) {
      return NextResponse.json({ error: permResult.reason }, { status: 403 });
    }

    const body = await request.json().catch(() => ({}));
    const parsed = bodySchema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json(
        { error: parsed.error.errors[0]?.message ?? "Invalid input" },
        { status: 400 }
      );
    }
    const { reason } = parsed.data;

    const updated = await withTenant(tenant.id, async (tx) => {
      const [current] = await tx
        .select()
        .from(fobRequests)
        .where(eq(fobRequests.id, requestId))
        .limit(1);

      if (!current) throw new Error("Request not found");
      if (current.paidAt) {
        throw new Error("Cannot require payment: this request has already been paid");
      }
      if (current.isOrphaned) {
        throw new Error("Cannot require payment on an orphaned request. Link it to a member first.");
      }
      if (!REQUIRABLE_STATUSES.includes(current.status)) {
        throw new Error(
          `Cannot require payment when status is "${current.status}". Must be submitted or awaiting approval.`
        );
      }

      return transitionRequest(tx, {
        requestId,
        tenantId: tenant.id,
        event: "PAYMENT_REQUIRED",
        actorId: auth.user.id,
        updates: {
          paymentExempt: false,
        },
        metadata: {
          reason,
          action: "admin_require_payment",
        },
      });
    });

    return NextResponse.json({ request: updated });
  } catch (err) {
    const message = err instanceof Error ? err.message : "Internal server error";
    const status =
      message.includes("Cannot") || message.includes("not found") ? 400 : 500;
    if (status === 500) console.error("Require payment error:", err);
    return NextResponse.json({ error: message }, { status });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { Permission } from "@accessbuddy/shared";
import { getAuthUser } from "@/lib/auth";
import { resolveTenant } from "@/lib/tenant";
import { checkPermission } from "@/lib/permissions";
import { withTenant } from "@/lib/with-tenant";
import { sendPaymentLinkEmail } from "@/lib/services/requests";

/**
 * Admin "resend payment link". No status change: re-emails the member the
 * pay link (and the signed cancel link) for a request that is still unpaid.
 * Creates the Stripe intent if the request never got one.
 */
export async function POST(
  _request: NextRequest,
  { params }: { params: Promise<{ slug: string; id: string }> }
) {
  try {
    const auth = await getAuthUser();
    if (!auth) {
      return NextResponse.json({ error: "Authentication required" }, { status: 401 });
    }

    const { slug, id: requestId } = await params;
    const tenant = await resolveTenant(slug);
    if (!tenant) {
      return NextResponse.json({ error: "Organisation not found" }, { status: 404 });
    }

    const permResult = checkPermission(auth, tenant.id, Permission.APPROVE_EXEMPTION);
    if (!permResult.granted) {
      return NextResponse.json({ error: permResult.reason }, { status: 403 });
    }

    const result = await withTenant(tenant.id, (tx) =>
      sendPaymentLinkEmail(tx, { requestId, tenantId: tenant.id, actorId: auth.user.id })
    );

    return NextResponse.json({ ok: true, sentTo: result.sentTo });
  } catch (err) {
    const message = err instanceof Error ? err.message : "Internal server error";
    const status =
      message.includes("Cannot") || message.includes("not found") ? 400 : 500;
    if (status === 500) console.error("Resend payment link error:", err);
    return NextResponse.json({ error: message }, { status });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { eq } from "drizzle-orm";
import { z } from "zod";
import { RequestStatus } from "@accessbuddy/shared";
import { fobRequests } from "@accessbuddy/db";
import { resolveTenant } from "@/lib/tenant";
import { withTenant } from "@/lib/with-tenant";
import { transitionRequest } from "@/lib/services/requests";
import { verifyCancelToken } from "@/lib/payment-links";

const bodySchema = z.object({
  token: z.string().min(1),
  reason: z.string().trim().min(1, "Reason is required").max(500),
});

// A member can only back out while the request is still waiting on them or
// on payment review. Once an admin has approved it the member uses the
// signed-in dashboard cancel, which goes through the normal ownership check.
const CANCELLABLE_BY_LINK: string[] = [
  RequestStatus.SUBMITTED,
  RequestStatus.AWAITING_PAYMENT,
  RequestStatus.AWAITING_EXEMPTION_REVIEW,
];

/**
 * Public, token-authenticated member cancel. The token is the HMAC issued
 * with the emailed payment link (see payment-links.ts). No session needed,
 * which matters because the member who abandoned payment may never have
 * signed in.
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string; id: string }> }
) {
  try {
    const { slug, id: requestId } = await params;
    const tenant = await resolveTenant(slug);
    if (!tenant) {
      return NextResponse.json({ error: "Organisation not found" }, { status: 404 });
    }

    const raw = await request.json().catch(() => ({}));
    const parsed = bodySchema.safeParse(raw);
    if (!parsed.success) {
      return NextResponse.json(
        { error: parsed.error.errors[0]?.message ?? "Invalid input" },
        { status: 400 }
      );
    }
    const { token, reason } = parsed.data;

    const verdict = verifyCancelToken({ token, tenantId: tenant.id, requestId });
    if (!verdict.valid) {
      const message =
        verdict.reason === "expired"
          ? "This cancel link has expired. Please contact the club to cancel your request."
          : "This cancel link is not valid.";
      return NextResponse.json({ error: message }, { status: 403 });
    }

    const updated = await withTenant(tenant.id, async (tx) => {
      const [req] = await tx
        .select()
        .from(fobRequests)
        .where(eq(fobRequests.id, requestId))
        .limit(1);

      if (!req) throw new Error("Request not found");
      if (req.status === RequestStatus.CANCELLED) {
        return req; // idempotent: clicking the link twice is fine
      }
      if (req.paidAt) {
        throw new Error("This request has already been paid and cannot be cancelled from this link. Please contact the club.");
      }
      if (!CANCELLABLE_BY_LINK.includes(req.status)) {
        throw new Error("This request can no longer be cancelled from this link. Please contact the club.");
      }

      return transitionRequest(tx, {
        requestId,
        tenantId: tenant.id,
        event: "CANCEL",
        actorId: null,
        metadata: { reason, action: "member_cancel_via_link" },
      });
    });

    return NextResponse.json({ ok: true, status: updated.status });
  } catch (err) {
    const message = err instanceof Error ? err.message : "Internal server error";
    const known =
      message.includes("Cannot") ||
      message.includes("not found") ||
      message.includes("no longer") ||
      message.includes("already been paid");
    if (!known) console.error("Cancel-by-token error:", err);
    return NextResponse.json({ error: known ? message : "Internal server error" }, { status: known ? 400 : 500 });
  }
}

